from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import combinations, product


def _interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        for chosen in combinations(
                [job for job in jobs if job["id"] not in blocked], k):
            ids = {job["id"] for job in chosen}
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in chosen:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            active = []
            valid = True
            for job in sorted(chosen, key=lambda row: (row["start"], row["end"])):
                active = [end for end in active if end > job["start"]]
                active.append(job["end"])
                if len(active) > capacity:
                    valid = False
                    break
            if not valid:
                continue

            selected = tuple(sorted(ids))
            value = sum(job["value"] for job in chosen)
            if (best_value is None or value > best_value or
                    (value == best_value and
                     ((tie == "smallest" and selected < best_ids) or
                      (tie == "largest" and selected > best_ids)))):
                best_value, best_ids = value, selected

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _ledger_solver(data):
    def rounded(numerator, denominator, mode):
        quotient, remainder = divmod(numerator, denominator)
        if mode == "half_up" and 2 * remainder >= denominator:
            quotient += 1
        return quotient

    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, mode)
        tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = (event.get("account", "default") + "|" +
               event.get("currency", "USD"))
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _dependency_solver(data):
    packages = data["packages"]
    names = sorted(packages)
    rows_by_version = {
        name: {row["version"]: row for row in packages[name]}
        for name in names
    }
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})

    def check(assignment):
        reached = set()
        edges = {}
        pending = []
        for name, (low, high) in data["roots"].items():
            pending.append((name, low, high, None))

        while pending:
            name, low, high, parent = pending.pop()
            version = assignment.get(name, -1)
            if version == -1 or not low <= version <= high:
                return None
            if version in blocked.get(name, []):
                return None
            if name in pins and version != pins[name]:
                return None
            if parent is not None:
                edges.setdefault(parent, set()).add(name)
            if name in reached:
                continue
            reached.add(name)
            row = rows_by_version[name][version]
            edges.setdefault(name, set())
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if not feature or feature in features:
                    pending.append((dep["name"], dep["min"], dep["max"], name))

        if reached != {name for name, version in assignment.items() if version != -1}:
            return None

        finished, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in edges.get(name, ())):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in reached):
            return None
        return {name: assignment[name] for name in names if name in reached}

    choices = []
    for name in names:
        versions = sorted(rows_by_version[name])
        choices.append([-1] + versions)
    for vector in product(*choices):
        assignment = dict(zip(names, vector))
        result = check(assignment)
        if result is not None:
            return {"versions": result}
    return {"error": "unsatisfiable"}


def _route_solver(data):
    import heapq

    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    start = data["start"]
    distances = {initial: start}
    queue = [(start, source, initial_mask, data["coupons"])]

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((duration, remaining - 1))
            for duration, next_remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask,
                                           next_remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": _interval_solver(1, "smallest"),
    "component_02": _interval_solver(2, "smallest"),
    "component_03": _interval_solver(1, "largest"),
    "component_04": _interval_solver(2, "largest"),
    "component_05": _interval_solver(1, "smallest"),
    "component_06": _ledger_solver,
    "component_07": _dependency_solver,
    "component_08": _route_solver,
}
